<section class="container section"><div class="section-heading"><div><p class="eyebrow">THE CONSIDERED EDIT</p><h2>Good things, <em>on repeat.</em></h2></div><a class="text-link" href="<?=e(url('catalog'))?>">Shop the edit →</a></div><div class="product-grid"><?php foreach(all('SELECT p.*,c.department FROM products p JOIN categories c ON c.id=p.category_id WHERE p.active=1 AND p.featured=1 ORDER BY p.id LIMIT 4') as $p)product_card($p);?></div></section>
